INSERT INTO `ai_prompt_templates` (`id`, `module`, `name`, `prompt_text`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'chat', 'Website Chat Assistant', 'You are Study First Info AI Assistant. Help students with queries about international education, universities, visa processes, IELTS/PTE requirements, scholarships, tuition fees, and admission procedures. Use the provided context to give accurate answers. Never fabricate university names. Never guarantee visa approvals. Be professional, friendly, and concise.', '[\"student_name\",\"country\",\"course\"]', 1, '2026-06-05 11:12:52', '2026-06-05 11:12:52'),
(2, 'lead_qualification', 'Lead Qualification Prompt', 'Analyze the following student profile and determine eligibility for international education. Consider: education level, GPA, IELTS/PTE scores, budget, study gap, and preferred country. Return a JSON response with: {\"score\": 0-100, \"category\": \"Hot Lead|Warm Lead|Cold Lead|Low Quality\", \"risks\": [], \"strengths\": [], \"next_steps\": [], \"reasoning\": \"\"}', '[\"gpa\",\"ielts_score\",\"budget\",\"country\",\"study_gap\"]', 1, '2026-06-05 11:12:52', '2026-06-05 11:12:52'),
(3, 'country_recommendation', 'Country Recommendation Prompt', 'Based on the student profile provided, recommend suitable countries for study abroad. Consider: academic profile, budget, IELTS score, study gap, and career goals. Only recommend from the provided list of available countries. Return JSON: {\"recommended\": [], \"risky\": [], \"budget_analysis\": \"\", \"reasoning\": \"\"}', '[\"profile\",\"available_countries\"]', 1, '2026-06-05 11:12:52', '2026-06-05 11:12:52'),
(4, 'counselor_draft', 'Counselor Email/WhatsApp Draft', 'Draft a professional and friendly message for the counselor to send to the student. Context: {{context}}. Intent: {{intent}}. Keep it concise, warm, and action-oriented.', '[\"context\",\"intent\",\"student_name\"]', 1, '2026-06-05 11:12:52', '2026-06-05 11:12:52'),
(5, 'visa_analysis', 'Visa Risk Analysis Prompt', 'Analyze the visa application risk for the following student profile applying to {{country}}. Consider: financial documents, study gap, academic scores, and previous visa history. Return JSON: {\"risk_level\": \"Low|Medium|High\", \"risk_factors\": [], \"recommendations\": [], \"interview_tips\": []}', '[\"country\",\"profile\",\"documents\"]', 1, '2026-06-05 11:12:52', '2026-06-05 11:12:52');
INSERT INTO `ai_settings` (`id`, `setting_key`, `setting_value`, `description`, `updated_at`) VALUES
(1, 'model', 'gpt-4o', 'OpenAI model to use', '2026-06-05 11:12:52'),
(2, 'temperature', '0.7', 'Response creativity (0-1)', '2026-06-05 11:12:52'),
(3, 'max_tokens', '2000', 'Maximum tokens per response', '2026-06-05 11:12:52'),
(4, 'enabled_modules', '{\"chat\":true,\"scoring\":true,\"qualification\":true,\"recommendation\":true,\"counselor\":true,\"visa\":true}', 'Active AI modules', '2026-06-05 11:12:52'),
(5, 'system_prompt_chat', 'You are Study First Info AI Assistant. You help students with international education queries about universities, visa processes, IELTS requirements, scholarships, and admission procedures. Always be professional, accurate, and helpful. Never fabricate university names or guarantee visa approvals.', 'Default chat system prompt', '2026-06-05 11:12:52'),
(6, 'whatsapp_number', '8801712345678', 'Company WhatsApp number for chatbot transfer', '2026-06-05 11:53:18'),
(7, 'company_name', 'Afsana Consultancy', 'Company name shown in chatbot', '2026-06-05 11:53:18'),
(8, 'chatbot_greeting', 'Hello! I am your AI Study Abroad Assistant from Afsana Consultancy. I can help you find the best country, university and visa guidance. How can I help you today?', 'Opening message of chatbot', '2026-06-05 11:53:18');
