INSERT INTO `country_requirements` (`id`, `country_name`, `education_requirements`, `ielts_min_overall`, `ielts_min_each`, `pte_min`, `budget_min_usd`, `budget_max_usd`, `visa_difficulty`, `study_gap_policy`, `intake_months`, `post_study_work`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Australia', 'Minimum 60% in HSC/A-Levels. Bachelor requires 65%+. Masters requires 60%+.', 6.0, 5.5, 50, 20000, 45000, 'Moderate', 'Up to 5 years gap acceptable with strong explanation. Large gaps require documentation.', 'February, July', '2–4 years Temporary Graduate visa (subclass 485)', 'Very popular destination. Strong employment outcomes. Regional areas offer extra benefits.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(2, 'United Kingdom', 'Minimum 55% in HSC/A-Levels. Bachelor requires 60%+. Masters requires 55%+.', 6.0, 5.5, 51, 25000, 50000, 'Moderate', 'Study gaps up to 3 years are generally acceptable with justification.', 'September, January', '2 years Graduate Route visa (3 years for PhD)', 'Shorter course durations (3-year Bachelor, 1-year Master) make it cost-effective.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(3, 'Canada', 'Minimum 60% in Secondary Education. University requires 65–70%.', 6.0, 5.5, 58, 18000, 40000, 'Moderate', 'Up to 3 years acceptable. Longer gaps need strong justification and employment proof.', 'January, May, September', 'PGWP up to 3 years. PR pathway through Express Entry.', 'Strong immigration pathway. PR-friendly. High demand destination.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(4, 'USA', 'GPA 2.5+ (4.0 scale). Most universities require 3.0+.', 6.5, 6.0, 58, 30000, 70000, 'Hard', 'Study gaps are generally NOT accepted. Continuous education strongly preferred.', 'August/September, January', 'OPT: 12 months (STEM: 36 months). No direct PR pathway.', 'Visa interview required. Very strict on study gap. SAT/GRE/GMAT often required.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(5, 'New Zealand', 'Minimum 50% in HSC. Bachelor requires 55%+.', 6.0, 5.5, 50, 18000, 35000, 'Easy', 'Study gaps up to 5 years usually accepted. Flexible policy.', 'February, July', 'Post Study Work Visa: 1–3 years depending on qualification.', 'Safe country. Growing tech and agriculture sectors. Good PR pathway.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(6, 'Ireland', 'Minimum 55% in HSC. University requires 60%+.', 6.0, 5.5, 55, 20000, 40000, 'Moderate', 'Up to 3–4 years generally acceptable.', 'September, January', 'Stay Back Visa: 1 year (Degree), 2 years (Masters/PhD)', 'Gateway to EU. English-speaking. Tech hub (Google, Facebook HQ in Dublin).', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(7, 'Germany', 'Strong academic background required. GPA equivalent minimum 2.5 German scale.', 6.5, 6.0, 58, 12000, 25000, 'Moderate', 'Study gaps up to 2 years acceptable with good justification.', 'April (Summer), October (Winter)', '18 months job-seeker visa after graduation.', 'Many tuition-free public universities. German language knowledge can be advantageous.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(8, 'Malaysia', 'Minimum 45% in HSC. Very flexible entry requirements.', 5.5, 5.0, 45, 8000, 18000, 'Easy', 'Very flexible. Gaps up to 7+ years often accepted.', 'January, May, September (rolling)', 'Limited work rights post-study.', 'Budget-friendly option. Good for students with lower scores or study gaps.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(9, 'Japan', 'HSC pass with decent grades. JLPT N4/N5 helpful for non-English programs.', 6.0, 5.5, 50, 12000, 28000, 'Moderate', 'Study gaps up to 2–3 years acceptable.', 'April, October', 'Job change visa available. Growing international graduate demand.', 'Technology, engineering, and arts programs popular. Safe country.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(10, 'Finland', 'Strong academic record. No strict GPA but competitive programs.', 6.0, 5.5, 50, 12000, 25000, 'Moderate', 'Relatively flexible. Up to 3 years generally fine.', 'September', 'Extended residence permit available for job search after graduation.', 'Many English-taught programs. High quality of life. Part of Schengen zone.', 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52');
