INSERT INTO `kb_faq_articles` (`id`, `category`, `question`, `answer`, `tags`, `view_count`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'IELTS', 'What is the minimum IELTS score required to study abroad?', 'Most countries require a minimum IELTS overall score of 6.0 with no band below 5.5. However, top universities in the UK, USA, and Canada may require 6.5 or 7.0. Australia and New Zealand generally accept 6.0+. Always check the specific university requirement as it varies.', 'ielts,score,requirement', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(2, 'IELTS', 'How many times can I take the IELTS exam?', 'There is no limit on how many times you can take IELTS. You can retake it as often as you like. Most universities accept your best score. We recommend waiting at least 3 months between attempts to properly prepare.', 'ielts,retake,exam', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(3, 'Visa', 'What documents are required for an Australian student visa?', 'Key documents include: Valid passport, Confirmation of Enrolment (CoE), IELTS/PTE results, bank statements showing sufficient funds, Overseas Student Health Cover (OSHC), academic transcripts, and a GTE (Genuine Temporary Entrant) statement.', 'visa,australia,documents', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(4, 'Visa', 'What is a GTE statement?', 'A GTE (Genuine Temporary Entrant) statement is a written document required for Australian student visa. It explains why you want to study in Australia, your ties to your home country, and your intention to return after completing your studies. A strong GTE significantly improves visa approval chances.', 'gte,visa,australia', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(5, 'Study Gap', 'How does a study gap affect my visa application?', 'A study gap is a period between your last formal education and when you plan to study again. For Australia and New Zealand, gaps up to 5 years are generally acceptable with proper explanation. For the USA, study gaps are viewed negatively. Always provide a clear, documented explanation for any gap period.', 'study gap,visa,education', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(6, 'Budget', 'How much money do I need to study in Australia?', 'For Australia, you typically need AUD 21,041 per year for living expenses plus tuition fees (AUD 20,000–45,000/year). Total annual budget: approximately AUD 41,000–66,000 (USD 27,000–44,000). You must show proof of sufficient funds in your bank account.', 'budget,australia,cost,money', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(7, 'Scholarship', 'Are there scholarships available for international students?', 'Yes! Major scholarships include: Australia Awards (Full), Chevening UK (Full), DAAD Germany (Full), Vanier Canada (Full PhD), Commonwealth Scholarship (Full), and many university-specific partial scholarships. Contact our counselors for personalized scholarship guidance based on your profile.', 'scholarship,funding,award', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(8, 'Application', 'How long does the university application process take?', 'Typically 4–8 weeks for most universities. Some competitive programs at top universities may take 3–4 months. We recommend applying at least 6 months before your intended intake date to allow time for visa processing (4–8 weeks additional).', 'application,timeline,process', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(9, 'Post-Study Work', 'Can I work after completing my studies?', 'Yes, most countries offer post-study work rights. Australia offers 2–4 years (subclass 485). UK offers 2 years Graduate Route. Canada offers up to 3 years PGWP with PR pathway. New Zealand offers 1–3 years. USA offers 12 months OPT (36 months for STEM).', 'work,post-study,visa,employment', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52'),
(10, 'General', 'What is the best country to study abroad?', 'The best country depends on your profile, budget, career goals, and visa history. Australia and Canada are top choices for PR pathways. UK offers shorter course durations. Germany has low tuition fees. Malaysia and New Zealand are budget-friendly. Our AI and counselors can give you personalized recommendations.', 'country,recommendation,best', 0, 1, '2026-06-05 11:26:52', '2026-06-05 11:26:52');
INSERT INTO `kb_scholarships` (`id`, `country_name`, `scholarship_name`, `provider`, `amount_usd`, `coverage_type`, `eligibility`, `min_ielts`, `min_gpa`, `deadline_notes`, `application_url`, `is_active`, `created_at`) VALUES
(1, 'Australia', 'Australia Awards Scholarship', 'Australian Government', 40000, 'Full', 'Open to developing country citizens. Must return home after studies.', 6.5, '70%+', 'Annual – usually April', 'https://www.dfat.gov.au/people-to-people/australia-awards', 1, '2026-06-05 11:26:52'),
(2, 'United Kingdom', 'Chevening Scholarship', 'UK Government', 35000, 'Full', 'For emerging leaders. Minimum 2 years work experience. IELTS 6.5+.', 6.5, '60%+', 'Annual – November', 'https://www.chevening.org/', 1, '2026-06-05 11:26:52'),
(3, 'Canada', 'Vanier Canada Graduate Scholarships', 'Government of Canada', 50000, 'Full', 'PhD students only. Must be nominated by university.', 7.0, '80%+', 'Annual – November', 'https://vanier.gc.ca/', 1, '2026-06-05 11:26:52'),
(4, 'New Zealand', 'NZ Development Scholarships', 'NZ Government', 30000, 'Full', 'For Pacific and developing countries. Priority for development sectors.', 6.0, '60%+', 'Annual – March', 'https://www.mfat.govt.nz/en/aid-and-development/new-zealand-scholarships/', 1, '2026-06-05 11:26:52'),
(5, 'Germany', 'DAAD Scholarship', 'DAAD Germany', 18000, 'Full', 'For international Masters and PhD students. German/English proficiency.', 6.0, '65%+', 'Annual – October/November', 'https://www.daad.de/en/', 1, '2026-06-05 11:26:52'),
(6, 'Australia', 'Destination Australia Scholarship', 'Australian Government', 15000, 'Partial', 'For studying at regional Australian institutions. Renewable annually.', 5.5, '55%+', 'Varies by institution', NULL, 1, '2026-06-05 11:26:52'),
(7, 'United Kingdom', 'Commonwealth Scholarship', 'Commonwealth Secretariat', 30000, 'Full', 'For commonwealth country citizens. Masters and PhD level.', 6.5, '65%+', 'Annual – December', 'https://cscuk.fcdo.gov.uk/', 1, '2026-06-05 11:26:52');
