INSERT INTO `lead_score_history` (`id`, `lead_id`, `score`, `category`, `reason`, `scored_by`, `created_at`) VALUES
(1, 8314, 35, 'Low Quality', '{\"reasoning\":\"The student profile lacks critical information necessary for assessing eligibility for international education in Australia. The absence of academic records, English proficiency test scores, budget, and preferred intake significantly limits the ability to determine the student\'s readiness and suitability for studying abroad. These are essential components for a successful application process. The lack of a study gap and previous visa refusals are positive aspects but do not compensate for the missing fundamental details. Hence, the student is categorized as a \'Low Quality\' lead until more information is provided.\",\"risks\":[\"Incomplete academic information\",\"English proficiency test scores not provided\",\"Budget not specified\",\"Preferred intake not specified\",\"Passport availability unknown\"],\"strengths\":[\"No study gap\",\"No previous visa refusals\"],\"next_steps\":[\"Obtain and provide detailed academic records and GPA scores\",\"Decide and undertake an English proficiency test (IELTS or PTE) and provide scores\",\"Clarify budget for studying in Australia\",\"Specify the preferred intake period\",\"Confirm availability of passport\"]}', 'ai', '2026-06-05 11:43:28'),
(2, 8315, 25, 'Low Quality', '{\"reasoning\":\"The student profile lacks critical information required to assess eligibility for international education in Australia. The absence of educational background, English proficiency scores, and a defined budget poses significant challenges. Additionally, the budget of below $10k is generally insufficient for studying in Australia unless scholarships or part-time work options are pursued. While the student has high priority and no previous visa refusals, the lack of detailed information makes it difficult to qualify as a strong candidate without further steps.\",\"risks\":[\"Missing educational background information\",\"No English proficiency test scores\",\"Very low budget for studying in Australia\",\"No specific course or intake preference\"],\"strengths\":[\"No previous visa refusals\",\"High priority for inquiry\"],\"next_steps\":[\"Obtain and provide details on educational background (high school, bachelor’s degree, etc.)\",\"Take an English proficiency test such as IELTS or PTE and achieve the required scores\",\"Consider increasing the budget or exploring scholarship options\",\"Specify a course of interest to tailor the application process\",\"Ensure passport availability for visa application\"]}', 'ai', '2026-06-05 13:31:30'),
(3, 8327, 45, 'Cold Lead', '{\"reasoning\":\"Azmol has a reasonable academic background with no study gap, making him a potential candidate for international education. However, the lack of English proficiency test scores, unspecified budget, and unknown passport status are significant barriers. These factors, combined with the low priority status and no specific course or intake preference, categorize this lead as \'Cold\'. To improve eligibility, Azmol needs to address these gaps and provide more information regarding his financial situation, English proficiency, and travel documentation.\",\"risks\":[\"Lack of specified English proficiency test scores\",\"No course or specific intake preference mentioned\",\"Budget not specified\",\"Low priority status\",\"Passport availability unknown\"],\"strengths\":[\"No study gap\",\"No previous visa refusals\",\"Reasonable academic performance in SSC and HSC\"],\"next_steps\":[\"Advise student to take an English proficiency test (IELTS or PTE) and provide scores\",\"Discuss potential courses and align with country-specific entry requirements\",\"Determine budget constraints for studying abroad\",\"Confirm passport availability to proceed with the visa application process\",\"Increase engagement to raise priority status\"]}', 'ai', '2026-06-10 10:49:35'),
(4, 8328, 40, 'Cold Lead', '{\"reasoning\":\"Shovo\'s profile currently lacks essential details required for effective evaluation of eligibility for international education. The absence of an English proficiency test score, unspecified budget, and lack of a preferred country or course significantly lower the score. The academic scores are moderate but might limit options depending on the target country\'s entry requirements. However, the absence of a study gap and any visa refusals are positive aspects. For Shovo to become a viable candidate for international education, additional information and preparation in key areas are necessary.\",\"risks\":[\"No specified English proficiency test scores\",\"No budget information provided\",\"No clear choice of course or country\",\"Low academic scores in SSC\"],\"strengths\":[\"No study gap\",\"No previous visa refusals\"],\"next_steps\":[\"Clarify the specific country and course of interest\",\"Obtain and prepare for an English proficiency test (IELTS/PTE) if required\",\"Determine available budget for international study\",\"Explore countries with flexible entry requirements for students with lower GPAs\"]}', 'ai', '2026-06-10 10:52:08'),
(5, 8329, 35, 'Cold Lead', '{\"reasoning\":\"Rakib Hasan Ovi has good academic scores with no study gap, which is a positive factor. However, the lack of a specified English proficiency test score, unclear budget, and unspecified country preference significantly impact his eligibility assessment for international education. Additionally, the low priority and the unknown status of his passport are concerns that need addressing to progress further in the application process.\",\"risks\":[\"No specified English proficiency test scores\",\"No specified budget\",\"Preferred country is unspecified (\'Others\')\",\"Low priority and current status\",\"Unknown passport status\"],\"strengths\":[\"Good academic performance in HSC and SSC\",\"No study gap\",\"No previous visa refusal\"],\"next_steps\":[\"Clarify the preferred country for study to narrow down options.\",\"Recommend taking an English proficiency test (IELTS/PTE) for eligibility in most international programs.\",\"Determine a clear budget for studying abroad to assess financial feasibility.\",\"Confirm the availability of a passport to ensure eligibility for a student visa.\"]}', 'ai', '2026-06-10 10:56:43'),
(6, 8330, 55, 'Warm Lead', '{\"reasoning\":\"Tahsan AB has a solid academic background with a bachelor\'s degree and a GPA of 3.54, which is a positive indicator for eligibility. However, the absence of English proficiency test scores, unspecified budget, and lack of a defined course of study pose significant risks. Additionally, passport availability is unknown, which could affect the visa application process. Addressing these issues is crucial to improving the lead\'s qualification for international education in Malta.\",\"risks\":[\"Lack of specified English proficiency test scores (IELTS/PTE)\",\"No specified budget\",\"Unknown passport availability\",\"No course specified for study\"],\"strengths\":[\"Good academic performance with a bachelor\'s GPA of 3.54\",\"No study gap\",\"No previous visa refusals\"],\"next_steps\":[\"Advise Tahsan AB to take an English proficiency test (IELTS or PTE) and submit the scores.\",\"Clarify the budget range for studying in Malta to ensure financial feasibility.\",\"Confirm passport availability for visa application purposes.\",\"Discuss and decide on a specific course of study in Malta.\"]}', 'ai', '2026-06-10 11:00:52'),
