(4, 1, 'English Proficiency (IELTS/PTE)', 1, 'Official test score report, usually within 2–3 years', NULL, '2026-06-05 11:26:52'),
(5, 1, 'Financial Evidence', 1, 'Bank statements showing sufficient funds (AUD 21,041/year minimum)', NULL, '2026-06-05 11:26:52'),
(6, 1, 'Overseas Student Health Cover (OSHC)', 1, 'Health insurance required for duration of study', NULL, '2026-06-05 11:26:52'),
(7, 1, 'Academic Transcripts', 1, 'Previous education records (HSC, Bachelor etc.)', NULL, '2026-06-05 11:26:52'),
